channel:
{{- if .Values.openclaw.feishu.enabled }}
"feishu": {
  "enabled": true,
  "domain": {{ .Values.openclaw.feishu.domain | quote }},
  "connectionMode": "websocket",
  "appId": "${FEISHU_APP_ID}",
  "appSecret": "${FEISHU_APP_SECRET}",
  "configWrites": false,
  "dmPolicy": "allowlist",
  "allowFrom": {{ .Values.openclaw.feishu.allowedUserIds | toJson }},
  "groupPolicy": {{ ternary "allowlist" "disabled" (not (empty .Values.openclaw.feishu.allowedGroupIds)) | quote }},
  "groupAllowFrom": {{ .Values.openclaw.feishu.allowedGroupIds | toJson }},
  "groupSenderAllowFrom": {{ .Values.openclaw.feishu.allowedUserIds | toJson }},
  "groupSessionScope": "group_sender",
  "requireMention": true,
  "tools": {
    "doc": false, "chat": false, "wiki": false, "drive": false,
    "perm": false, "scopes": false, "bitable": false, "base": false
  }
}{{- if or .Values.openclaw.slack.enabled .Values.openclaw.msteams.install .Values.openclaw.msteams.enabled }},{{- end }}
{{- end }}

env:
{{- if .Values.openclaw.feishu.enabled }}
{{- range $env, $key := dict "FEISHU_APP_ID" .Values.openclaw.feishu.appIdKey "FEISHU_APP_SECRET" .Values.openclaw.feishu.appSecretKey }}
- name: {{ $env }}
  valueFrom:
    secretKeyRef:
      name: {{ $.Values.openclaw.feishu.existingSecret | quote }}
      key: {{ $key | quote }}
{{- end }}
{{- end }}

validation:
{{- if .Values.openclaw.feishu.enabled -}}
{{- if not (and .Values.modules.execution.enabled .Values.openclaw.enabled) -}}
{{- fail "openclaw.feishu.enabled requires modules.execution.enabled and openclaw.enabled" -}}
{{- end -}}
{{- if not .Values.openclaw.feishu.existingSecret -}}
{{- fail "openclaw.feishu.existingSecret is required when Feishu is enabled" -}}
{{- end -}}
{{- if not (has .Values.openclaw.feishu.domain (list "feishu" "lark")) -}}
{{- fail "openclaw.feishu.domain must be feishu or lark" -}}
{{- end -}}
{{- if empty .Values.openclaw.feishu.allowedUserIds -}}
{{- fail "openclaw.feishu.allowedUserIds must contain at least one Feishu open_id" -}}
{{- end -}}
{{- range concat .Values.openclaw.feishu.allowedUserIds .Values.openclaw.feishu.allowedGroupIds -}}
{{- if or (not (kindIs "string" .)) (empty .) (eq . "*") -}}
{{- fail "Feishu allowlists require explicit, nonempty user/group IDs" -}}
{{- end -}}
{{- end -}}
{{- end -}}
